// b402.js — Binance x402 (b402) payment gate. "no @b402/sdk on npm"
const { decodePaymentSignatureHeader } = require('@x402/core/http');
const chainId = config.bnbNetwork === 'bsc' ? 56 : 97;
const eip155  = 'eip155:' + chainId;
const usdt = chainId === 56 ? config.usdtMainnet : config.usdtTestnet;
const HIRE_PRICE_ATOMIC = '500000';           // $0.50, USDT 6dp

function buildRequirements(amountAtomic = HIRE_PRICE_ATOMIC) {
  return { scheme: 'exact', network: eip155, amount: amountAtomic, asset: usdt,
    payTo: config.bnbPayTo, maxTimeoutSeconds: 300,
    extra: { name: 'Tether USD', version: '1',
             assetTransferMethod: 'eip3009', signerAddress: config.bnbPayTo } };
}

function teslaSign(privateKey, body, timestamp) {
  return crypto.createSign('RSA-SHA256').update(body + timestamp, 'utf8')
               .end().sign(loadRsaKey(privateKey), 'base64');
}

async function b402Post(path, payload) {
  const body = JSON.stringify(payload);
  const timestamp = Date.now().toString();
  const res = await fetch(baseUrl + path, { method: 'POST', headers: {
      'Content-Type': 'application/json',
      'X-Tesla-ClientId':        process.env.B402_CLIENT_ID,
      'X-Tesla-SignAccessToken': process.env.B402_ACCESS_TOKEN,
      'X-Tesla-Timestamp':       timestamp,
      'X-Tesla-Signature':       teslaSign(privateKey, body, timestamp),
    }, body, signal: AbortSignal.timeout(15000) });
  const envelope = JSON.parse(await res.text());
  if (envelope.code !== '000000') throw new Error('b402 ' + path + ': code ' + envelope.code);
  return envelope.data;
}

async function verifySettle(paymentHeader) {
  const decoded = decodePaymentSignatureHeader(paymentHeader);
  const request = { paymentPayload: decoded,
                    paymentRequirements: buildRequirements(), x402Version: 2 };
  const verifyData = await b402Post('/papi/v2/b402/verify', request);
  if (!verifyData?.isValid) return { ok: false, error: verifyData?.invalidReason };
  const settleData = await b402Post('/papi/v2/b402/settle', request);   // fail closed
  if (!settleData || settleData.success !== true || !settleData.transaction)
    return { ok: false, error: 'BNB settlement failed or unconfirmed' };
  return { ok: true, settleTx: settleData.transaction, payer: verifyData.payer, network: eip155 };
}
